<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_admin();$flash=pull_flash();$users=$pdo->query("SELECT u.*,COUNT(t.id) template_count FROM users u LEFT JOIN twibbons t ON t.owner_id=u.id GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kelola Pengguna — Bingkaiin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">B</span>Bingkaiin</a><nav class="nav-links"><a href="./">Beranda</a><a href="dashboard">Dashboard</a><a class="active" href="users">Pengguna</a><a href="admin">Template</a></nav></div></header><main class="container"><div class="page-head dashboard-head"><div><span class="eyebrow">Administrator</span><h1 class="page-title" style="margin-top:12px">Kelola pengguna</h1><p class="subtitle">Atur hak akses dan pantau akun yang menggunakan Bingkaiin.</p></div><span class="btn btn-secondary"><?=count($users)?> akun</span></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><section class="panel"><div style="overflow-x:auto"><table class="w-full text-left"><thead class="text-xs uppercase tracking-wider text-slate-500"><tr><th class="p-4">Pengguna</th><th class="p-4">Role</th><th class="p-4">Template</th><th class="p-4">Bergabung</th><th class="p-4 text-right">Aksi</th></tr></thead><tbody><?php foreach($users as $item):?><tr class="border-t border-slate-100"><td class="p-4"><strong><?=e($item['name'])?></strong><br><small class="text-slate-500"><?=e($item['email'])?></small></td><td class="p-4"><span class="visibility <?=$item['role']==='admin'?'visibility-public':'visibility-unlisted'?>"><?=e(ucfirst($item['role']))?></span></td><td class="p-4"><?=(int)$item['template_count']?></td><td class="p-4 text-sm text-slate-500"><?=date('d M Y',strtotime($item['created_at']))?></td><td class="p-4"><div class="flex justify-end gap-2"><?php if((int)$item['id']!==(int)current_user()['id']):?><form method="post" action="admin"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user_role"><input type="hidden" name="user_id" value="<?=(int)$item['id']?>"><input type="hidden" name="role" value="<?=$item['role']==='admin'?'user':'admin'?>"><button class="btn btn-secondary btn-sm"><?=$item['role']==='admin'?'Jadikan user':'Jadikan admin'?></button></form><form method="post" action="admin" onsubmit="return confirm('Hapus akun dan seluruh templatenya?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_user"><input type="hidden" name="user_id" value="<?=(int)$item['id']?>"><button class="btn btn-danger btn-sm">Hapus</button></form><?php else:?><small class="text-slate-400">Akun Anda</small><?php endif?></div></td></tr><?php endforeach?></tbody></table></div></section></main><footer class="footer">Bingkaiin · Produk digital dari Apins Digital</footer></body></html>
